import{_ as a,o as r,c as o,a5 as n}from"./chunks/framework.Cooo9kuv.js";const c=JSON.parse('{"title":"按范围提取","description":"","frontmatter":{"标题":"922-PDF批量拆分提取工具","日期":"2026-04-23T00:00:00.000Z","修改日期":"2026-05-27T00:00:00.000Z","作者":"softbangong","状态":"publish","分类":["PDF批处理"],"标签":["PDF单页提取","PDF工具下载","PDF批量处理","PDF批量拆分","PDF拆分提取工具","PDF指定页提取","PDF按范围提取","PDF编辑工具","pdf页面提取","办公PDF工具"]},"headers":[],"relativePath":"md/PDF批处理/922-PDF批量拆分提取工具.md","filePath":"md/PDF批处理/922-PDF批量拆分提取工具.md"}'),p={name:"md/PDF批处理/922-PDF批量拆分提取工具.md"};function s(e,t,g,l,d,h){return r(),o("div",null,[...t[0]||(t[0]=[n('<p>这个工具可以帮你把PDF文件按需要拆分成多个部分。不管是想提取前几页、单独拿出某一页、还是把一整本电子书按章节拆成多个文件，这个工具都能一键搞定。支持同时处理文件夹里所有的PDF文件，还能自动保持原来的文件夹结构，非常适合需要整理大量PDF资料的人使用。</p><h1 id="按范围提取" tabindex="-1">按范围提取 <a class="header-anchor" href="#按范围提取" aria-label="Permalink to &quot;按范围提取&quot;">​</a></h1><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/image-14.png" alt=""></p><h1 id="提取单页" tabindex="-1">提取单页 <a class="header-anchor" href="#提取单页" aria-label="Permalink to &quot;提取单页&quot;">​</a></h1><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/image-15.png" alt=""></p><h1 id="提取指定页" tabindex="-1">提取指定页 <a class="header-anchor" href="#提取指定页" aria-label="Permalink to &quot;提取指定页&quot;">​</a></h1><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/image-16.png" alt=""></p><h1 id="批量拆分" tabindex="-1">批量拆分 <a class="header-anchor" href="#批量拆分" aria-label="Permalink to &quot;批量拆分&quot;">​</a></h1><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/image-17.png" alt=""></p><h2 id="功能特点" tabindex="-1">功能特点 <a class="header-anchor" href="#功能特点" aria-label="Permalink to &quot;功能特点&quot;">​</a></h2><ul><li><strong>按范围提取</strong>：指定起始页和结束页，提取连续页面</li><li><strong>提取单页</strong>：提取PDF中的任意单页</li><li><strong>提取指定页</strong>：输入页码列表（如2,4,6,8），提取不连续页面</li><li><strong>批量拆分</strong>：按多个范围同时拆分成多个PDF文件</li><li><strong>拖拽支持</strong>：支持拖拽PDF文件或文件夹到输入框</li></ul><p><strong>按范围提取</strong>：指定起始页和结束页，把这个范围内的所有页面提取出来生成一个新PDF。</p><p><strong>提取单页</strong>：输入具体的页码，把这一页单独提取出来成为一个PDF文件。</p><p><strong>提取指定页</strong>：输入任意多个页码，用逗号分隔，比如输入”2,4,6,8”，程序会把这些页面合并到一个PDF文件中。</p><p><strong>批量拆分</strong>：一次性输入多个范围，比如”1-5/6-10/11-15”，程序会把PDF按这些范围拆成多个文件。</p><p><strong>文件夹批量处理</strong>：支持拖入整个文件夹，自动找出所有PDF文件批量处理，省去一个个选择的麻烦。</p><p><strong>保持文件夹结构</strong>：勾选这个选项后，输出的文件会按照原来的文件夹层级存放，方便管理。</p><p><strong>穿透子文件夹</strong>：勾选后，程序会搜索文件夹里所有子文件夹中的PDF文件，不遗漏任何文件。</p><h2 id="页面范围格式说明" tabindex="-1">页面范围格式说明 <a class="header-anchor" href="#页面范围格式说明" aria-label="Permalink to &quot;页面范围格式说明&quot;">​</a></h2><table tabindex="0"><thead><tr><th>功能</th><th>格式示例</th><th>说明</th></tr></thead><tbody><tr><td>按范围提取</td><td>1-5</td><td>提取第1页到第5页</td></tr><tr><td>提取单页</td><td>3</td><td>提取第3页</td></tr><tr><td>提取指定页</td><td>2,4,6,8</td><td>提取第2、4、6、8页</td></tr><tr><td>提取指定页</td><td>2,4,6,8</td><td>提取第2、4、6、8页</td></tr></tbody></table><h2 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h2><ul><li>支持 <code>.pdf</code> 格式的PDF文档</li><li>程序会创建新的PDF文件，不会修改原始文件</li></ul><h3 id="实际使用场景示例" tabindex="-1">实际使用场景示例 <a class="header-anchor" href="#实际使用场景示例" aria-label="Permalink to &quot;实际使用场景示例&quot;">​</a></h3><h3 id="场景1-提取合同指定页面" tabindex="-1">场景1：提取合同指定页面 <a class="header-anchor" href="#场景1-提取合同指定页面" aria-label="Permalink to &quot;场景1：提取合同指定页面&quot;">​</a></h3><p>场景描述：收到一份50页的合同扫描件，只需要把第15到20页的附件内容提取出来给法务审核。</p><p>操作步骤。</p><p><strong>第一步</strong>，把合同PDF拖入程序输入框。</p><p><strong>第二步</strong>，切换到”按范围提取”标签页。</p><p><strong>第三步</strong>，起始页输入15，结束页输入20。</p><p><strong>第四步</strong>，点击”提取范围页面”按钮。</p><p>预期结果：程序在原文件目录创建”合同名”文件夹，里面有”合同名_提取_15-20.pdf”文件。</p><hr><h3 id="场景2-批量提取多本电子书的目录页" tabindex="-1">场景2：批量提取多本电子书的目录页 <a class="header-anchor" href="#场景2-批量提取多本电子书的目录页" aria-label="Permalink to &quot;场景2：批量提取多本电子书的目录页&quot;">​</a></h3><p>场景描述：下载了5本电子书，每本都需要把前5页（目录）提取出来单独保存，方便快速查阅。</p><p>操作步骤。</p><p><strong>第一步</strong>，把存放这5本电子书的文件夹拖入程序。</p><p><strong>第二步</strong>，勾选”穿透子文件夹”（如果有子文件夹的话）。</p><p><strong>第三步</strong>，切换到”按范围提取”标签页，起始页输入1，结束页输入5。</p><p><strong>第四步</strong>，点击”提取范围页面”按钮。</p><p>预期结果：每个电子书旁边会生成一个”提取”文件夹，里面有对应的”电子书名_提取_1-5.pdf”文件。</p><hr><h3 id="场景3-把扫描版书籍按章节拆分" tabindex="-1">场景3：把扫描版书籍按章节拆分 <a class="header-anchor" href="#场景3-把扫描版书籍按章节拆分" aria-label="Permalink to &quot;场景3：把扫描版书籍按章节拆分&quot;">​</a></h3><p>场景描述：有一份300页的扫描版书籍，需要按每50页一章节拆成6个文件，方便在电子书上分章节阅读。</p><p>操作步骤。</p><p><strong>第一步</strong>，把书籍PDF拖入程序输入框。</p><p><strong>第二步</strong>，切换到”批量拆分”标签页。</p><p><strong>第三步</strong>，在页面范围输入”1-50/51-100/101-150/151-200/201-250/251-300”。</p><p><strong>第四步</strong>，输出前缀填写”章节”。</p><p><strong>第五步</strong>，点击”批量拆分”按钮。</p><p>预期结果：在原文件目录创建”书籍名”文件夹，里面有6个文件，分别是”章节_1_1-50.pdf”到”章节_6_251-300.pdf”。</p><hr><h3 id="数据存储位置" tabindex="-1">数据存储位置 <a class="header-anchor" href="#数据存储位置" aria-label="Permalink to &quot;数据存储位置&quot;">​</a></h3><p><strong>输入文件</strong>：存储位置为你选择或拖入的原始PDF文件所在位置，程序不会修改原始文件。</p><p><strong>输出文件</strong>：存储位置为原文件目录下的同名文件夹内，或者你在输出路径中指定的目录。</p><h3 id="注意事项-1" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项-1" aria-label="Permalink to &quot;注意事项&quot;">​</a></h3><p>重要提示：处理前请备份重要数据，程序只生成新的PDF文件，不会修改或删除你的原始文件，但养成备份习惯总没错。</p><p>操作过程中<strong>不要关闭程序窗口</strong>，等待处理完成提示出现。</p><p>页码输入从1开始，不是从0开始。比如要提取第1页，起始页就填1。</p><p>结束页必须大于等于起始页，否则程序会报错。</p><p>批量处理时，如果某个文件处理失败，程序会跳过这个文件继续处理下一个，不会中断整个批量操作。</p><p>如果程序无响应，耐心等待片刻，大文件处理可能需要较长时间。</p><p>首次使用建议<strong>先用少量文件测试</strong>，确认效果后再批量处理。</p><h1 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h1><p><strong>Q: PDF批量拆分提取哪个工具好用？</strong><br> A: 推荐使用这个开源免费的PDF批量拆分提取工具，支持按范围提取、单页提取、提取指定页、批量拆分等多种功能。只需选择文件，设置范围，点击开始，批量处理瞬间完成。</p><p><strong>Q: 提取后会修改原文件吗？</strong><br> A: 不会。程序会创建新的PDF文件，不会修改原始文件，可以放心使用。</p><p><strong>Q: 支持提取不连续的页面吗？</strong><br> A: 支持！在”提取指定页”功能中，输入页码列表（用逗号分隔，如2,4,6,8），即可提取不连续的多个页面。</p><p><strong>Q: 可以同时拆分成多个文件吗？</strong><br> A: 可以！使用”批量拆分”功能，输入多个范围（格式：1-5/6-10/11-15），程序会同时拆分成多个独立的PDF文件。</p><p><strong>Q: 支持什么PDF格式？</strong><br> A: 支持标准 .pdf 格式的PDF文档。</p><h1 id="程序使用环境及相关说明" tabindex="-1">程序使用环境及相关说明 <a class="header-anchor" href="#程序使用环境及相关说明" aria-label="Permalink to &quot;程序使用环境及相关说明&quot;">​</a></h1><p><strong>1、适用的系统环境说明</strong>：</p><p>win7及以上64位windows操作系统 ，  **注意事项：**win32位系统以及mac系统需要额外定制开发</p><p><strong>2、关于使用限制</strong>：</p><p>①无需注册、登录等限制，直接使用，  ②没有电脑台数限制，  ③无使用时间限制、不联网本地使用、确保数据安全</p><p>**3、程序如何安装：**不需要安装，按照说明使用即可。</p><p><strong>特别注意</strong>：请先测试，注意备份原文件，之后再批量使用，避免不可逆损失。</p><h1 id="程序使用说明" tabindex="-1">程序使用说明 <a class="header-anchor" href="#程序使用说明" aria-label="Permalink to &quot;程序使用说明&quot;">​</a></h1><p><strong>解压后直接使用即可，不需要安装，程序可以放在任意位置</strong></p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/image-43.png" alt=""></p><hr><p><strong>程序下载链接：</strong> <a href="https://www.softbangong.com/2723.html" target="_blank" rel="noreferrer">https://www.softbangong.com/2723.html</a></p>',80)])])}const P=a(p,[["render",s]]);export{c as __pageData,P as default};
